import{_ as a,o as r,c as o,a2 as s}from"./chunks/framework.DDY-poMm.js";const p=JSON.parse('{"title":"理财类业务","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/wealth.md","filePath":"zh/guide/wealth.md","lastUpdated":1790683574000}'),l={name:"zh/guide/wealth.md"};function e(d,t,n,i,h,c){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="理财类业务" tabindex="-1">理财类业务 <a class="header-anchor" href="#理财类业务" aria-label="Permalink to &quot;理财类业务&quot;">​</a></h1><p>平台提供理财、质押挖矿、助力贷三类增值玩法，以及新币申购。是否对用户开放由「基础配置 → 玩法配置」控制；结算方式在后台「玩法配置」页统一设定。</p><h2 id="理财" tabindex="-1">理财 <a class="header-anchor" href="#理财" aria-label="Permalink to &quot;理财&quot;">​</a></h2><p>按周期计息的资产管理产品。用户端分成<strong>三个分区</strong>：<strong>普通理财 / 会员专区 / 增值收益</strong>，产品创建时选定归属分区；会员专区的产品可设置 VIP 等级门槛，等级不够的用户看得到但买不了。</p><h3 id="产品配置-后台「理财产品」" tabindex="-1">产品配置（后台「理财产品」） <a class="header-anchor" href="#产品配置-后台「理财产品」" aria-label="Permalink to &quot;产品配置（后台「理财产品」）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>标题 / 图标 / 币种 / 分类</td><td>用户端展示的名称、图标、计价币种与所属分区</td></tr><tr><td>天数</td><td>锁定周期，到期结算</td></tr><tr><td>最小 / 最大日利率（%）</td><td>展示给用户的收益区间；实际按后台结算规则计息</td></tr><tr><td>违约利率（%）</td><td>用户提前赎回时按此比例扣除违约金，余额退回</td></tr><tr><td>最小 / 最大金额</td><td>单笔认购的额度范围</td></tr><tr><td>限购次数</td><td>单个用户可购买的次数，<strong>0 表示不限</strong></td></tr><tr><td>VIP 等级</td><td>购买门槛</td></tr><tr><td>热销 / 启用 / 排序</td><td>用户端的角标、上下架与展示顺序</td></tr></tbody></table><h3 id="订单与收益" tabindex="-1">订单与收益 <a class="header-anchor" href="#订单与收益" aria-label="Permalink to &quot;订单与收益&quot;">​</a></h3><ul><li>「理财订单」可查每笔认购的产品、金额、创建与到期时间、状态；可对符合条件的订单执行<strong>赎回</strong>（需输入订单号二次确认）</li><li>用户端「我的理财」显示<strong>当日赚取</strong>（只统计当天派发的收益）与<strong>累计收益</strong>（全时段派发总和），两者口径不同，不是同一个数字</li><li>结算方式在「玩法配置 → 理财结算类型」中选：<strong>每日</strong>结算、<strong>到期</strong>结算，或<strong>指定天数</strong>（1–28 日之间）</li></ul><h2 id="质押挖矿" tabindex="-1">质押挖矿 <a class="header-anchor" href="#质押挖矿" aria-label="Permalink to &quot;质押挖矿&quot;">​</a></h2><p>用户锁定资产获取收益，产品在后台「挖矿产品」维护，字段与理财产品一致（天数、利率区间、额度、限购次数等），另有「前端是否展示」开关。</p><ul><li><strong>质押限购</strong>：可针对<strong>单个用户</strong>单独设置某产品的可购买次数（例如给测试账号放开限制），需从「挖矿产品」页面进入对应产品后新增</li><li>「质押订单」可查每笔质押的项目、累计收益、到期时间与状态</li><li>结算方式在「玩法配置 → 质押挖矿结算类型」设定</li></ul><h2 id="助力贷" tabindex="-1">助力贷 <a class="header-anchor" href="#助力贷" aria-label="Permalink to &quot;助力贷&quot;">​</a></h2><p>借贷类玩法，额度、周期、利率在后台配置，申请需经后台审核。</p><h2 id="申购-打新" tabindex="-1">申购（打新） <a class="header-anchor" href="#申购-打新" aria-label="Permalink to &quot;申购（打新）&quot;">​</a></h2><p>新币认购玩法。项目在后台「币种发行」创建，经历「筹备中 → 订阅 → 审批 → 进行中 → 发行」的状态流转：</p><ol><li><strong>筹备中</strong>：填写发行资料（图文），此时用户不可见</li><li><strong>开放申购</strong>：用户可提交订阅申请（「申购订单」可查）</li><li><strong>审批</strong>：运营在「新币订阅」对每笔申请同意或拒绝</li><li><strong>发布</strong>：币种正式发行，通过审批的用户获得对应数量</li></ol><div class="warning custom-block"><p class="custom-block-title">配置提醒</p><p>创建申购项目时，<strong>「购买上限」必须填写</strong>，留空可能导致用户端下单异常。</p></div><hr><h2 id="运营通用提示" tabindex="-1">运营通用提示 <a class="header-anchor" href="#运营通用提示" aria-label="Permalink to &quot;运营通用提示&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">收益结算</p><p>理财类业务的收益由系统的定时任务统一结算派发，派发有<strong>幂等控制</strong>，同一期不会重复发放。如果发现某一期收益未到账，先在后台查看该期产品的状态与订单记录，再联系技术方排查——<strong>不要用后台调账手工补发</strong>，那会绕过流水口径，让后续核账更难。</p></div><div class="warning custom-block"><p class="custom-block-title">修改进行中的产品</p><p>产品<strong>已经有用户参与之后</strong>，不要再修改它的收益率、周期等核心参数。已参与的用户是按原参数计算预期收益的，中途改动会引发客诉。需要调整时，正确做法是下架旧产品、新建一个。</p></div><div class="danger custom-block"><p class="custom-block-title">额度与上限</p><p>配置产品时请填写完整的额度与单用户上限。留空的上限字段可能导致下单环节异常。</p></div>',22)])])}const u=a(l,[["render",e]]);export{p as __pageData,u as default};
